INSERT IGNORE INTO `site_portal_pages` (`id`, `category`, `page_key`, `page_title`, `badge`, `heading`, `subheading`, `content_data`, `status`, `created_at`, `updated_at`) VALUES
('1', 'overview', 'mission-vision', 'Vision & Mission - Bhabha University Bhopal', 'Our Purpose & Direction', 'Vision & <em>Mission</em>', 'The guiding philosophy that shapes every decision, programme, and initiative at Bhabha University.', '{\"page_icon\":\"fa-eye\",\"cards\":[{\"label\":\"Our Purpose\",\"heading\":\"Our <em>Vision<\\/em>\",\"body\":\"<p>The vision of Bhabha University is to become a <strong>globally recognised centre of learning<\\/strong> that provides high-quality, research-driven education — from diploma to doctoral programmes — nurturing graduates who are not only academically excellent but also socially responsible and globally competitive.<\\/p><p>The university aspires to contribute meaningfully to society through teaching and research, helping achieve global sustainability. It aims to produce leaders in science, technology, management, healthcare, law, and other disciplines.<\\/p>\"},{\"label\":\"What Drives Us\",\"heading\":\"Our <em>Mission<\\/em>\",\"body\":\"<ul><li>To provide greater access to higher education for all — especially to socially and educationally underprivileged youth — upholding the principle of social equity.<\\/li><li>To make learning exciting through excellent, integrative teaching strategies driven by curiosity and creativity.<\\/li><li>To facilitate and promote entry into research at an early age through a flexible, borderless curriculum and hands-on research projects.<\\/li><li>To encourage and facilitate inter-institutional and international exchange programmes and collaborations in teaching and research.<\\/li><li>To build a culture of integrity, innovation, inclusivity, and academic rigor that prepares students for real-world challenges.<\\/li><li>To foster entrepreneurship, problem-solving, and leadership skills that enable graduates to create value for society.<\\/li><\\/ul>\"},{\"label\":\"Philosophy\",\"heading\":\"Our <em style=\\\"color:#FFC107 !important;\\\">Core Philosophy<\\/em>\",\"style\":\"background:linear-gradient(135deg,#0A1B54,#061D7C); border-color:#0A1B54;\",\"label_style\":\"color:#FFC107 !important;\",\"heading_style\":\"color:#ffffff !important;\",\"body\":\"<p style=\\\"color:#FFFFFF !important; font-size:15.5px !important; line-height:1.75 !important;\\\">At Bhabha University, we believe that <strong style=\\\"color:#FFC107 !important;\\\">education is transformation<\\/strong>. Every student who walks through our doors carries with them the potential to change their family, their community, and the world. Our role is to unlock that potential through rigorous academics, mentorship, and an environment that celebrates both excellence and compassion.<\\/p>\"}]}', '1', '2026-09-09 12:24:01', '2026-09-09 12:26:57'),
('2', 'overview', 'values', 'Core Values - Bhabha University Bhopal', 'Institutional Ethos', 'Our <em>Core Values</em>', 'The foundational principles of integrity, excellence, and inclusivity that guide our community.', '{\"page_icon\":\"fa-compass\",\"values\":[{\"title\":\"Excellence in Education\",\"icon\":\"fa-graduation-cap\",\"desc\":\"Striving for highest quality in pedagogy, research, and holistic student development.\"},{\"title\":\"Integrity & Ethics\",\"icon\":\"fa-shield\",\"desc\":\"Upholding honesty, transparency, and accountability across all academic and administrative endeavors.\"},{\"title\":\"Innovation & Research\",\"icon\":\"fa-lightbulb-o\",\"desc\":\"Fostering a forward-thinking culture of curiosity, scientific inquiry, and technological development.\"},{\"title\":\"Diversity & Inclusivity\",\"icon\":\"fa-users\",\"desc\":\"Ensuring equitable opportunities and mutual respect for individuals of all backgrounds and perspectives.\"},{\"title\":\"Community & Social Responsibility\",\"icon\":\"fa-heart\",\"desc\":\"Serving the community and contributing meaningfully to sustainable national progress.\"},{\"title\":\"Leadership & Global Competence\",\"icon\":\"fa-globe\",\"desc\":\"Equipping students with future-ready skills, resilience, and collaborative leadership.\"}]}', '1', '2026-09-09 12:24:01', '2026-09-09 12:40:40'),
('3', 'overview', 'why-us', 'Why Choose Bhabha University - Bhabha University Bhopal', 'Why Choose Us', 'Why <em>Bhabha University</em>', '10 distinctive pillars that make Bhabha University the premier destination for ambitious learners.', '{\"page_icon\":\"fa-star\",\"pillars\":[{\"num\":\"01\",\"title\":\"UGC Recognised & Statutory Approvals\",\"desc\":\"Approved by UGC, AICTE, PCI, DCI, and BCI ensuring global validity of degrees.\"},{\"num\":\"02\",\"title\":\"32-Acre Ultra-Modern Campus\",\"desc\":\"Lush green, eco-friendly campus with smart classrooms, advanced labs, and sports arenas.\"},{\"num\":\"03\",\"title\":\"Industry-Aligned Curriculum\",\"desc\":\"Curricula designed with industry experts, live projects, and hands-on skill development.\"},{\"num\":\"04\",\"title\":\"Research & Innovation Ecosystem\",\"desc\":\"Dedicated incubation center, patent cell, commercial pharma labs, and generous seed funding.\"},{\"num\":\"05\",\"title\":\"Excellent Placement Records\",\"desc\":\"300+ top recruiters including TCS, Wipro, Infosys, Ranbaxy, Cipla, and Cognizant.\"},{\"num\":\"06\",\"title\":\"Distinguished Faculty\",\"desc\":\"Learn from PhD scholars, renowned professors, and experienced industry veterans.\"},{\"num\":\"07\",\"title\":\"Entrepreneurship & Start-up Incubation\",\"desc\":\"Incubating student ventures with funding guidance, mentorship, and workspace support.\"},{\"num\":\"08\",\"title\":\"Global Collaborations & MOUs\",\"desc\":\"International and national exchange partnerships for joint research and global exposure.\"},{\"num\":\"09\",\"title\":\"Comprehensive Scholarships\",\"desc\":\"Merit and need-based scholarships empowering students from diverse socioeconomic strata.\"},{\"num\":\"10\",\"title\":\"Vibrant Campus Life\",\"desc\":\"Clubs, cultural fests, sports leagues, radio broadcasts, and community outreach.\"}]}', '1', '2026-09-09 12:24:01', '2026-09-21 03:29:10'),
('4', 'overview', 'about', 'About Us - Bhabha University Bhopal | Best University in MP', 'Legacy of Excellence', 'About <em>Bhabha University</em>', 'Established under the Madhya Pradesh Niji Vishwavidyalaya Adhiniyam — pioneering research, innovation, and industry-oriented education.', '{\"page_icon\":\"fa-university\",\"stats\":[{\"num\":\"32+\",\"label\":\"Acres Lush Green Campus\",\"icon\":\"fa-map-o\"},{\"num\":\"20,000+\",\"label\":\"Alumni Network Across India\",\"icon\":\"fa-users\"},{\"num\":\"100+\",\"label\":\"Advanced Laboratories\",\"icon\":\"fa-flask\"},{\"num\":\"300+\",\"label\":\"Corporate Placement Partners\",\"icon\":\"fa-briefcase\"}],\"overview_text\":\"<p>Bhabha University was established under the Madhya Pradesh Niji Vishwavidyalaya (Sthapana Avam Sanchalan) Adhiniyam, 2007. Named after the visionary scientist Dr. Homi Jehangir Bhabha, the university embodies his spirit of scientific inquiry, nation-building, and technological self-reliance.</p><p>Offering multidisciplinary undergraduate, postgraduate, and doctoral degrees in Engineering, Pharmacy, Dental Sciences, Management, Computer Applications, Agriculture, Law, and Humanities, the university is committed to fostering future-ready professionals.</p>\",\"chancellor_name\":\"Dr. Sunil Kapoor\",\"chancellor_title\":\"Hon\'ble Chancellor\",\"chancellor_message\":\"Our mission is to create a dynamic academic environment that inspires students to achieve excellence and lead with purpose in an interconnected world.\",\"vc_name\":\"Prof. (Dr.) Dilip Kumar\",\"vc_title\":\"Hon\'ble Vice Chancellor\",\"vc_message\":\"We focus on multidisciplinary research, student-centric innovation, and ethical leadership to shape global citizens equipped for emerging industry frontiers.\"}', '1', '2026-09-09 12:24:01', '2026-09-21 03:29:10'),
('5', 'overview', 'hotel', 'Hotel Management - Bhabha University Bhopal Madhya Pradesh', 'Professional Hospitality', 'RKDF Institute of <em>Hotel Management</em>', 'Excellence in hospitality training, culinary arts, and tourism operations.', '{\"page_icon\":\"fa-cutlery\",\"body\":\"<p>The RKDF Institute of Hotel Management & Catering Technology under Bhabha University provides comprehensive training in food production, front office management, accommodation operations, and beverage service. Equipped with commercial demo kitchens, mock guest rooms, and a training restaurant, students gain hands-on professional hospitality competencies.<\\/p>\"}', '1', '2026-09-09 12:24:01', '2026-09-09 12:26:57'),
('6', 'overview', 'university', 'About University - Bhabha University Bhopal Madhya Pradesh', 'Campus Highlights', 'Campus <em>Overview</em>', 'State-of-the-art facilities, academic infrastructure, and vibrant collegiate culture.', '{\"page_icon\":\"fa-building\",\"body\":\"<p>Spread across 32 acres of lush green campus in Bhopal, Bhabha University offers state-of-the-art academic auditoriums, Wi-Fi enabled digital classrooms, computer centers with 1 Gbps internet connectivity, dedicated hostel facilities for male and female students, medical healthcare center, and expansive sports complexes.</p>\"}', '1', '2026-09-09 12:24:01', '2026-09-21 03:29:10'),
('7', 'reports', 'nirf', 'NIRF Rankings & Submission Reports - Bhabha University Bhopal', 'National Ranking Framework', 'NIRF <em>Submission Reports</em>', 'National Institutional Ranking Framework (NIRF) data submitted to the Ministry of Education, Government of India.', '{\"academic_year\":\"2025-26\",\"docs\":[{\"code\":\"OVERALL\",\"title\":\"Overall NIRF Report\",\"discipline\":\"University-Wide Comprehensive Data\",\"url\":\"upload\\/media\\/e7499fa68f8c45da5de179244ce06453.pdf\"},{\"code\":\"DENTAL\",\"title\":\"Dental Sciences NIRF\",\"discipline\":\"Bhopal Dental College & Research Centre\",\"url\":\"upload\\/media\\/d67c5238d424c629091bc9d04f151c1f.pdf\"},{\"code\":\"AGRI\",\"title\":\"Agriculture Sciences NIRF\",\"discipline\":\"Faculty of Agriculture\",\"url\":\"upload\\/media\\/4d6fe79475b028260ee9c2d26e5e13eb.pdf\"},{\"code\":\"ENGG\",\"title\":\"Engineering & Technology NIRF\",\"discipline\":\"Faculty of Engineering\",\"url\":\"upload\\/media\\/10e4e67d2bd221beb9bd9f25c14beb44.pdf\"},{\"code\":\"PHARM\",\"title\":\"Pharmacy Sciences NIRF\",\"discipline\":\"Faculty of Pharmacy\",\"url\":\"upload\\/media\\/609d5cf76b83a259a1ba4eac912aa03e.pdf\"},{\"code\":\"LAW\",\"title\":\"Law & Legal Studies NIRF\",\"discipline\":\"Faculty of Law\",\"url\":\"upload\\/media\\/57d360d54612fee3c65985bc9ad0eba0.pdf\"},{\"code\":\"MGMT\",\"title\":\"Management Studies NIRF\",\"discipline\":\"Faculty of Management\",\"url\":\"upload\\/media\\/809e6f0f24caae71558512a96eb824ba.pdf\"},{\"code\":\"COLLEGE\",\"title\":\"Colleges & Institutions NIRF\",\"discipline\":\"Institutional Composite\",\"url\":\"upload\\/media\\/b962b78c485d262ff1e7f07aeb9e4792.pdf\"}]}', '1', '2026-09-09 12:24:01', '2026-09-09 12:26:57'),
('8', 'reports', 'iqac', 'Internal Quality Assurance Cell (IQAC) - Bhabha University Bhopal', 'Quality Assurance', 'Internal Quality <em>Assurance Cell</em>', 'Systematic planning, guiding, and monitoring quality enhancement and sustenance initiatives.', '{\n    \"hero_title\": \"Internal Quality Assurance Cell (IQAC)\",\n    \"hero_desc\": \"Established in pursuance of National Action Plan for performance evaluation, assessment, and quality up-gradation of institutions of higher education.\",\n    \"chairperson\": \"Prof. (Dr.) Dilip Kumar (Vice-Chancellor)\",\n    \"director\": \"Dr. S. K. Gupta (Director IQAC)\"\n}', '1', '2026-09-09 12:24:01', '2026-09-25 16:34:12'),
('9', 'reports', 'auditreport', 'Finance & Audit Report - Bhabha University Bhopal', 'Financial Transparency', 'Finance & <em>Audit Report</em>', 'Official financial reports, audit statements and balance sheets — reflecting our commitment to transparency.', '{\"docs\":[{\"title\":\"Audit Report 2023-24\",\"year\":\"2023-24\",\"url\":\"upload\\/media\\/a0bae7c93fe4ef327d1e52224c1b8ee8.pdf\"},{\"title\":\"Audit Report — Ayushmati Education Society 2023\",\"year\":\"2022-23\",\"url\":\"upload\\/media\\/6f7c8abe8bbf0031ca3051545b2eac18.pdf\"},{\"title\":\"Balance Sheet 2023-24\",\"year\":\"2023-24\",\"url\":\"upload\\/media\\/c0ca03c0cd958e2bd34d2c186ac3d5c4.pdf\"},{\"title\":\"Balance Sheet 2021-22 — Ayushmati Education Society\",\"year\":\"2021-22\",\"url\":\"upload\\/media\\/18a8b68a5dcc6fdc4682eb26d790d238.pdf\"}]}', '1', '2026-09-09 12:24:01', '2026-09-09 12:26:57'),
('10', 'reports', 'ugc-proforma', 'UGC Proforma - Bhabha University Bhopal', 'Regulatory Compliance', 'UGC <em>Proforma</em>', 'University Grants Commission information in prescribed format — ensuring regulatory transparency.', '{\"pdf_title\":\"Filled UGC Proforma Information in Prescribed Format\",\"pdf_url\":\"upload\\/media\\/8a5cc8e8a663be0f26243b584eab0a19.pdf\",\"note\":\"Bhabha University is recognised by the University Grants Commission (UGC) under Section 2(f) and 12(B) of the UGC Act, 1956.\"}', '1', '2026-09-09 12:24:01', '2026-09-09 12:26:57'),
('11', 'reports', 'downlod1', 'Downloads - Bhabha University Bhopal Madhya Pradesh', 'Student Form Downloads', 'Student <em>Form Downloads</em>', 'Official university forms for migration certificates, duplicate marksheets, provisional degrees, and transcripts.', '{\"forms\":[{\"title\":\"Notice University Certificate (Fees)\",\"url\":\"upload\\/media\\/43220e47ba4dc41f2feedaa84d2b75b1.pdf\"},{\"title\":\"Issue of Duplicate Name Correction In MarkSheet New\",\"url\":\"upload\\/media\\/4dfae40cb8bf1f1b5d0fb8b63d542672.pdf\"},{\"title\":\"Application Form for Issue of Provisional \\/ Migration Certificate\",\"url\":\"upload\\/media\\/019c18458f2b9b6485deb792fc7c3c2b.pdf\"},{\"title\":\"Application for Issue of Degree Certificate\",\"url\":\"upload\\/media\\/9feec28a9ceec19a4a7cef2f7f07795a.pdf\"},{\"title\":\"Application Form for Issue of Transcript\",\"url\":\"upload\\/media\\/Application Form for Issue of transcript (1).pdf\"}]}', '1', '2026-09-09 12:24:01', '2026-09-09 12:26:57'),
('12', 'legal', 'privacy-policy', 'Privacy Policy - Bhabha University Bhopal Madhya Pradesh', 'Legal & Compliance', 'Privacy <em>Policy</em>', 'Official data privacy terms, student information protection, and disclosure guidelines.', '{\"body\":\"<p>The <strong>BHABHA UNIVERSITY<\\/strong> protects the personal information collected from and about students, graduates, staff and other business partners. This includes the training of employees and the establishment of control systems for the responsible use of personal information that is accessible to BHABHA UNIVERSITY employees while performing work-related duties. The BHABHA UNIVERSITY directs its employees to exercise caution when making personal information available to others and not to give others access to BHABHA UNIVERSITY information or passwords. All full-time and part-time employees of the BHABHA UNIVERSITY, as well as student interns, are required to sign the employee non-disclosure & confidential agreement.<\\/p><h4>In general, access to personal information is limited to the following:<\\/h4><ul><li>An individual accessing his or her own personal information.<\\/li><li>An employee or agent of The BHABHA UNIVERSITY with authorized access based on a legitimate academic or business need to know.<\\/li><li>Any organization or person authorized by the individual to receive the information.<\\/li><li>Any authorized legal or governing body or representative or circumstance where The BHABHA UNIVERSITY is compelled to comply with the release of personal information.<\\/li><li>Any other individual or entity as permitted by law where deemed to be necessary for the reasonable conduct of BHABHA UNIVERSITY business.<\\/li><\\/ul><h4>Privacy<\\/h4><ul><li>The BHABHA UNIVERSITY does not sell, rent or otherwise make available a student\'s personal information to any third parties for marketing purposes.<\\/li><li>The BHABHA UNIVERSITY may confirm inquiries as to whether an individual holds a designation or degree in good standing from The BHABHA UNIVERSITY.<\\/li><li>The BHABHA UNIVERSITY releases name and address information to a limited number of professional industry organizations regarding students expressly for the purpose of informing them of eligibility for membership.<\\/li><\\/ul>\"}', '1', '2026-09-09 12:24:01', '2026-09-09 12:26:57'),
('13', 'legal', 'term-and-condition', 'Terms & Conditions - Bhabha University Bhopal Madhya Pradesh', 'Legal Terms', 'Terms & <em>Conditions</em>', 'Rules, guidelines, and terms governing website usage, online admissions, and campus regulations.', '{\"body\":\"<p>Welcome to Bhabha University. By accessing our website, applying for admissions, or using our campus services, you agree to comply with and be bound by the following terms and conditions. The content of the pages of this website is for your general information and use only. It is subject to change without notice.<\\/p><h4>Admissions & Academic Conduct<\\/h4><ul><li>All information provided during admission registration must be accurate and truthful. Any misrepresentation will result in immediate disqualification or cancellation of enrollment.<\\/li><li>Students are expected to adhere to the code of conduct, maintain minimum attendance criteria as prescribed by statutory bodies, and refrain from any acts of ragging or indiscipline.<\\/li><li>The university reserves the right to modify fee structures, examination schedules, and academic calendars in compliance with regulatory directives.<\\/li><\\/ul>\"}', '1', '2026-09-09 12:24:01', '2026-09-09 12:26:57'),
('14', 'legal', 'refund-policy', 'Refund and Cancellation Policy - Bhabha University Bhopal', 'Fee Policies', 'Refund & <em>Cancellation Policy</em>', 'Institutional policy regarding fee refunds, withdrawals, and cancellation in accordance with UGC norms.', '{\"body\":\"<p>Bhabha University follows the fee refund guidelines stipulated by the University Grants Commission (UGC) and state regulatory directives.<\\/p><h4>Cancellation & Refund Guidelines<\\/h4><ul><li>If a student chooses to withdraw before the formal commencement of the academic session, the entire fee deposited after deducting a nominal processing fee as per UGC rules shall be refunded.<\\/li><li>Requests for cancellation must be formally submitted in writing along with original fee receipts to the Registrar\'s office.<\\/li><li>Refunds are processed via online bank transfer directly to the student or parent bank account within the statutory timeline.<\\/li><\\/ul>\"}', '1', '2026-09-09 12:24:01', '2026-09-09 12:26:57'),
('15', 'legal', 'mandatory-disclosure', 'Mandatory Disclosure - Bhabha University Bhopal', 'Statutory Compliance', 'Mandatory <em>Disclosure</em>', 'Statutory public disclosures under AICTE, UGC, and State Regulatory Commissions.', '{\"body\":\"<p>Under the regulations of statutory authorities including AICTE and UGC, Bhabha University publishes comprehensive mandatory disclosures detailing academic programs, infrastructure, faculty credentials, and governance bodies.</p>\",\"docs\":[{\"title\":\"Mandatory Public Disclosure \\u2014 Bhabha University Bhopal\",\"url\":\"upload/media/12dfaac45ab95d2c718f63563d7c5a28.pdf\"}]}', '1', '2026-09-09 12:24:01', '2026-09-30 15:35:21'),
('16', 'student_publications', 'admissions', 'Admissions Overview - Bhabha University Bhopal', 'Admission Gateway', 'Admissions <em>Overview</em>', 'Comprehensive admission guide, eligibility criteria, counselling schedule, and application steps.', '{\"steps\":[{\"step\":\"01\",\"title\":\"Choose Your Program\",\"desc\":\"Browse through 85+ undergraduate, postgraduate, and doctoral degree offerings.\"},{\"step\":\"02\",\"title\":\"Fill Online Application\",\"desc\":\"Complete the online registration form and upload academic marksheets.\"},{\"step\":\"03\",\"title\":\"Document Verification & Fee\",\"desc\":\"Receive counselling confirmation and submit admission seat fee.\"},{\"step\":\"04\",\"title\":\"Orientation & Classes\",\"desc\":\"Attend induction week and commence your transformative university journey.\"}]}', '1', '2026-09-09 12:24:01', '2026-09-21 03:29:10'),
('17', 'student_publications', 'scholarship', 'Scholarship Programs - Bhabha University Bhopal', 'Financial Assistance', 'Scholarship <em>Schemes</em>', 'State and Central Government scholarships, merit awards, and sports concessions.', '{\"schemes\":[{\"title\":\"Post-Matric Scholarship for SC\\/ST\\/OBC\",\"authority\":\"Government of Madhya Pradesh\",\"desc\":\"Full or partial tuition fee reimbursement for eligible category students.\"},{\"title\":\"Mukhyamantri Medhavi Vidyarthi Yojana (MMVY)\",\"authority\":\"MP Higher Education Dept\",\"desc\":\"Financial support for meritorious students achieving top percentile in board exams.\"},{\"title\":\"Merit-Based Academic Concession\",\"authority\":\"Bhabha University Merit Board\",\"desc\":\"Fee concessions for university rank holders, sports champions, and defense wards.\"}]}', '1', '2026-09-09 12:24:01', '2026-09-09 12:26:57'),
('18', 'student_publications', 'career', 'Careers & Opportunities - Bhabha University Bhopal', 'Work With Us', 'Careers at <em>Bhabha University</em>', 'Join an esteemed fraternity of academicians, researchers, and administrators.', '{\"body\":\"<p>Bhabha University offers competitive compensation, research incentives, sabbatical leaves, and health coverage for teaching and non-teaching personnel. We are committed to attracting distinguished faculty and dynamic administrators who are passionate about student success and groundbreaking research.<\\/p>\"}', '1', '2026-09-09 12:24:01', '2026-09-09 12:26:57'),
('19', 'student_publications', 'activities', 'Campus Activities - Bhabha University Bhopal', 'Student Life', 'Campus <em>Activities & Clubs</em>', 'Extracurricular clubs, cultural fests, sports tournaments, and community volunteering.', '{\"body\":\"<p>Campus life at Bhabha University is vibrant and holistic. Students participate in technical hackathons, cultural festivals like Tarang, inter-university sports championships, NSS community camps, and debate societies, fostering well-rounded personality development.<\\/p>\"}', '1', '2026-09-09 12:24:01', '2026-09-09 12:26:57'),
('20', 'student_publications', 'magazine', 'University Magazine & Publications - Bhabha University', 'Annual Publications', 'University <em>Magazine</em>', 'Explore \'Bhabha Spandan\' and annual creative literary anthologies celebrating institutional achievements.', '{\"flagship\":{\"title\":\"Bhabha Spandan\",\"edition\":\"2024-25 Edition\",\"subtitle\":\"Annual University Magazine\",\"desc\":\"A showcase of creative literature, student expressions, technological breakthroughs, and institutional glory.\",\"pdf_url\":\"upload\\/media\\/bhabha_spandan_2024.pdf\"},\"archive\":[{\"title\":\"Bhabha Spandan 2023-24\",\"theme\":\"Innovation & Sustainable Future\",\"url\":\"#\"},{\"title\":\"Bhabha Spandan 2022-23\",\"theme\":\"Silver Jubilee Celebrations\",\"url\":\"#\"},{\"title\":\"Bhabha Spandan 2021-22\",\"theme\":\"Resilience & Digital Education\",\"url\":\"#\"}]}', '1', '2026-09-09 12:24:01', '2026-09-09 12:26:57'),
('21', 'student_publications', 'newsletter', 'E-Newsletter & Quarterly Digest - Bhabha University', 'Quarterly Bulletin', 'University <em>E-Newsletter</em>', 'Quarterly digest documenting campus news, faculty awards, conference milestones, and student triumphs.', '{\n    \"latest\": {\n        \"title\": \"Bhabha Chronicle \\u2014 Q2 2026 Edition\",\n        \"volume\": \"Vol. 6 | Issue 2\",\n        \"period\": \"Apr \\u2013 Jun 2026\",\n        \"badge\": \"LATEST RELEASE\",\n        \"desc\": \"Dive into the latest quarterly happenings across all 11 constituent institutes of Bhabha University, featuring major commercial research launches, international academic collaborations, academic accreditations, and our highest placement records.\",\n        \"highlights\": [\n            \"Launch of 14 Commercial Herbal Formulations (15th August)\",\n            \"Record campus placement offers with TCS, Infosys, Sun Pharma\",\n            \"Inauguration of New AI & Robotics Centre of Excellence\",\n            \"Faculty patent grants in advanced drug delivery systems\"\n        ],\n        \"pdf_url\": \"upload\\/research\\/overview.pdf\"\n    },\n    \"archive\": [\n        {\n            \"title\": \"New Horizons in Innovation & Academic Milestones\",\n            \"vol\": \"Vol. 6 | Issue 1\",\n            \"date\": \"Jan \\u2013 Mar 2026\",\n            \"size\": \"16 Pages \\u2022 PDF\",\n            \"topics\": [\n                \"National Conference on Smart Computing & IoT Solutions\",\n                \"Annual Sports Meet & Cultural Fest \'Tarang 2026\'\",\n                \"Launch of Entrepreneurship & Incubation EDC Cell\"\n            ],\n            \"url\": \"upload\\/research\\/overview.pdf\"\n        },\n        {\n            \"title\": \"Convocation Special & Industry Collaboration Report\",\n            \"vol\": \"Vol. 5 | Issue 4\",\n            \"date\": \"Oct \\u2013 Dec 2025\",\n            \"size\": \"20 Pages \\u2022 PDF\",\n            \"topics\": [\n                \"5th Annual University Convocation & Gold Medalists\",\n                \"MOU Signing with leading pharmaceutical & IT giants\",\n                \"Winter Faculty Development Programme (FDP) outcomes\"\n            ],\n            \"url\": \"upload\\/research\\/overview.pdf\"\n        },\n        {\n            \"title\": \"Pharmacy Research & Healthcare Outreach Focus\",\n            \"vol\": \"Vol. 5 | Issue 3\",\n            \"date\": \"Jul \\u2013 Sep 2025\",\n            \"size\": \"18 Pages \\u2022 PDF\",\n            \"topics\": [\n                \"Community Health Camps conducted across Bhopal district\",\n                \"International Pharmacy Week & Clinical Trial Workshop\",\n                \"Student innovators receive State Science Council Grant\"\n            ],\n            \"url\": \"upload\\/research\\/overview.pdf\"\n        },\n        {\n            \"title\": \"Engineering Innovations & Smart Campus Upgrades\",\n            \"vol\": \"Vol. 5 | Issue 2\",\n            \"date\": \"Apr \\u2013 Jun 2025\",\n            \"size\": \"16 Pages \\u2022 PDF\",\n            \"topics\": [\n                \"Solar-powered green campus initiative completion\",\n                \"Hackathon 2025 winners develop Agriculture IoT kit\",\n                \"Alumni Mentorship series conducted across all departments\"\n            ],\n            \"url\": \"upload\\/research\\/overview.pdf\"\n        },\n        {\n            \"title\": \"Academic Year Kickoff & Placement Milestones\",\n            \"vol\": \"Vol. 5 | Issue 1\",\n            \"date\": \"Jan \\u2013 Mar 2025\",\n            \"size\": \"14 Pages \\u2022 PDF\",\n            \"topics\": [\n                \"Orientation of 2025 academic batch across 50+ courses\",\n                \"Over 850 campus placement offers recorded in Phase 1\",\n                \"IQAC quality enhancement framework rollout\"\n            ],\n            \"url\": \"upload\\/research\\/overview.pdf\"\n        },\n        {\n            \"title\": \"20 Years of Educational Excellence \\u2014 2004 to 2024\",\n            \"vol\": \"Vol. 4 | Special Issue\",\n            \"date\": \"Annual Roundup 2024\",\n            \"size\": \"32 Pages \\u2022 PDF\",\n            \"topics\": [\n                \"Two-decade institutional milestone commemorative report\",\n                \"Notable Alumni hall of fame & global contributions\",\n                \"Strategic 2030 vision roadmap of Bhabha University\"\n            ],\n            \"url\": \"upload\\/research\\/overview.pdf\"\n        }\n    ]\n}', '1', '2026-09-09 12:24:01', '2026-09-25 16:34:12'),
('22', 'student_publications', 'blogs', 'Research, Academic & Tech Blogs - Bhabha University', 'Thought Leadership', 'Academic & <em>Tech Blogs</em>', 'Perspectives, research breakthroughs, and insights from faculty, researchers, and student innovators.', '{\"articles\":[{\"title\":\"The Future of AI in Pharmaceutical Drug Discovery\",\"author\":\"Dr. A. K. Sharma\",\"category\":\"Pharmacy & AI\",\"date\":\"2025-01-15\",\"read_time\":\"5 min read\",\"summary\":\"How machine learning algorithms and computational molecular modeling are revolutionizing pharmacology research at Bhabha University.\"},{\"title\":\"Sustainable Green Energy Solutions for Modern Campuses\",\"author\":\"Prof. R. C. Verma\",\"category\":\"Engineering\",\"date\":\"2025-01-08\",\"read_time\":\"4 min read\",\"summary\":\"Analyzing the environmental and operational impacts of our 500kW rooftop solar energy installation.\"},{\"title\":\"Emerging Trends in Cyber Security and Data Protection\",\"author\":\"Dr. Neha Singh\",\"category\":\"Computer Science\",\"date\":\"2024-12-22\",\"read_time\":\"6 min read\",\"summary\":\"Essential strategies for safeguarding institutional information assets in the era of quantum computing.\"}]}', '1', '2026-09-09 12:24:01', '2026-09-09 12:26:57'),
('23', 'legal', 'public-md', 'Public Mandatory Disclosure - Bhabha University Bhopal', 'Public Regulatory Disclosure', 'Public Mandatory <em>Disclosure</em>', 'Public statutory declarations, AICTE approvals, and university proforma documents.', '{\"body\":\"<p>Under statutory guidelines of UGC and AICTE, the complete institutional records, faculty roster, and building infrastructure audits are available for public scrutiny.<\\/p>\",\"forms\":[{\"title\":\"Notice University Certificate (Fees)\",\"url\":\"upload\\/media\\/43220e47ba4dc41f2feedaa84d2b75b1.pdf\"},{\"title\":\"Issue of Duplicate Name Correction In MarkSheet New\",\"url\":\"upload\\/media\\/4dfae40cb8bf1f1b5d0fb8b63d542672.pdf\"},{\"title\":\"Application Form for Issue of Provisional \\/ Migration Certificate\",\"url\":\"upload\\/media\\/019c18458f2b9b6485deb792fc7c3c2b.pdf\"},{\"title\":\"Application for Issue of Degree Certificate\",\"url\":\"upload\\/media\\/9feec28a9ceec19a4a7cef2f7f07795a.pdf\"},{\"title\":\"Application Form for Issue of Transcript\",\"url\":\"upload\\/media\\/Application Form for Issue of transcript (1).pdf\"}]}', '1', '2026-09-09 12:26:57', '2026-09-09 12:26:57'),
