('26', 'campus_life', 'clubs', 'University Clubs & Societies - Bhabha University Bhopal', 'Co-Curricular Excellence & Student Life', 'University <em>Clubs &amp; Societies</em>', 'Learn Beyond Classrooms • Lead with Purpose • Grow with Values • Create Impact.', '{\"meta_description\":\"Explore vibrant Student & University Clubs at Bhabha University Bhopal — Abhivyakti Club, Unload Pittara, Staff Club, Environment Club, Legal Aid Clinic, Khelo Bhabha, Nav Grah Vatika, EDC & AD-MAD Club. Learn beyond classrooms, lead with purpose, and create impact.\",\"meta_keywords\":\"Bhabha University clubs, student societies Bhopal, Abhivyakti cultural club, Unload Pittara mental wellness, Khelo Bhabha sports, Environment club 1101 trees, Legal aid clinic, Nav Grah Vatika, EDC incubation, AD MAD club\",\"page_icon\":\"fa-users\",\"badge\":\"Co-Curricular Excellence & Student Life\",\"intro_p\":\"At Bhabha University, Bhopal, learning goes beyond classrooms. It is about discovering passions, nurturing talents, building character and preparing future-ready professionals! At Bhabha University, clubs are not merely extracurricular activities; they are platforms that inspire aspirations, cultivate leadership, foster well-being and shape socially responsible citizens ready to lead the future.\",\"motto_label\":\"OUR MOTTO\",\"motto\":[{\"icon\":\"fa-book\",\"title\":\"Learn Beyond Classrooms\"},{\"icon\":\"fa-bullseye\",\"title\":\"Lead with Purpose\"},{\"icon\":\"fa-heart\",\"title\":\"Grow with Values\"},{\"icon\":\"fa-rocket\",\"title\":\"Create Impact\"}],\"metrics\":[{\"icon\":\"fa-cubes\",\"num\":\"9+ Specialized\",\"label\":\"Clubs & Cells\"},{\"icon\":\"fa-paint-brush\",\"num\":\"35+ Activities\",\"label\":\"Cultural & Creative\"},{\"icon\":\"fa-smile-o\",\"num\":\"1,700+ Scholars\",\"label\":\"Mentored for Wellness\"},{\"icon\":\"fa-tree\",\"num\":\"1,101 Trees\",\"label\":\"Green Mission 2026\"},{\"icon\":\"fa-gavel\",\"num\":\"18+ Years\",\"label\":\"Free Legal Aid Service\"}],\"sec_label\":\"Active Student Societies\",\"sec_heading\":\"Our Flagship Clubs & Specialized Cells\",\"clubs\":[{\"id\":\"abhivyakti\",\"name\":\"Abhivyakti Club\",\"desig\":\"Personality Development, Communication, Creativity & Life-Career Readiness\",\"desk_label\":\"Cultural & Creative Platform\",\"desk_icon\":\"fa-ticket\",\"pill_text\":\"Personality & Cultural Platform\",\"pill_icon\":\"fa-star\",\"visual_bg\":\"linear-gradient(145deg, #040F4A 0%, #061D7C 60%, #0D2CB5 100%)\",\"visual_icon\":\"fa-paint-brush\",\"visual_cat\":\"Cultural & Arts\",\"visual_name\":\"Abhivyakti\",\"visual_tag\":\"35+ Annual Activities\",\"quote\":\"Empowering students to express, excel and evolve through nearly 35 cultural, creative and skill-oriented activities.\",\"body_p1\":\"With nearly 35 cultural, creative and skill-oriented activities, <strong>Abhivyakti Club</strong> serves as a dynamic platform for personality development, leadership, communication, creativity and life-career readiness, empowering students to express, excel and evolve.\",\"body_p2\":\"From theatrical productions and musical performances to public speaking debates and art exhibitions, the club provides an inclusive stage for every scholar to explore their latent artistic abilities while cultivating decisive stage presence and self-confidence.\",\"chips\":[\"35+ Annual Cultural Activities\",\"Personality Grooming & Soft Skills\",\"Public Speaking & Debate Mastery\",\"Creative Arts & Theatrical Productions\",\"Inter-University Mega Festivals\"]},{\"id\":\"unload-pittara\",\"name\":\"Unload Pittara — Mental Well-Being Club\",\"desig\":\"Emotional Well-Being, Stress Management & Psychological Resilience\",\"desk_label\":\"Psychological Wellness & Emotional Support\",\"desk_icon\":\"fa-heart\",\"pill_text\":\"MP Police Community Collaboration\",\"pill_icon\":\"fa-star\",\"visual_bg\":\"linear-gradient(145deg, #064E3B 0%, #047857 60%, #059669 100%)\",\"visual_icon\":\"fa-heartbeat\",\"visual_cat\":\"Mental Well-Being\",\"visual_name\":\"Unload Pittara\",\"visual_tag\":\"1,700+ Mentored\",\"quote\":\"Because every voice deserves to be heard — providing a safe and supportive space for self-expression, mental wellness, and care.\",\"body_p1\":\"Because every voice deserves to be heard, <strong>Unload Pittara Club</strong> provides a safe and supportive space for emotional well-being, self-expression, stress management and psychological resilience, fostering a culture of care and belonging.\",\"body_p2\":\"Having mentored more than <strong>1,700 students</strong> through seminars and workshops on happy living, the club has emerged as a significant initiative for promoting emotional wellness. It has also actively collaborated with <strong>MP Police under Community Policing initiatives</strong>, extending support to underprivileged children during moments of distress and vulnerability.\",\"chips\":[\"1,700+ Students Mentored\",\"MP Police Community Policing Linkage\",\"Happy Living Seminars & Workshops\",\"Underprivileged Child Support Initiatives\",\"Peer Counselling & Safe Listening Circles\"]},{\"id\":\"staff-club\",\"name\":\"Staff Club\",\"desig\":\"Professional Engagement, Collaboration, Educator Well-Being & Community Care\",\"desk_label\":\"Institutional Culture & Faculty Synergy\",\"desk_icon\":\"fa-handshake-o\",\"pill_text\":\"Educator Well-Being & Family Care\",\"pill_icon\":\"fa-star\",\"visual_bg\":\"linear-gradient(145deg, #1E1B4B 0%, #312E81 60%, #4338CA 100%)\",\"visual_icon\":\"fa-users\",\"visual_cat\":\"Faculty Synergy\",\"visual_name\":\"Staff Club\",\"visual_tag\":\"Inclusive Culture\",\"quote\":\"Recognizing that empowered educators inspire empowered learners — promoting collaboration and a positive institutional culture.\",\"body_p1\":\"Recognizing that empowered educators inspire empowered learners, the <strong>Staff Club</strong> promotes professional engagement, well-being, collaboration and a positive institutional culture across the University.\",\"body_p2\":\"The club regularly organizes different workshops, fun engagement activities and provides <strong>free career counselling support for the children of staff members</strong>, fostering a caring, egalitarian, and inclusive university community.\",\"chips\":[\"Professional Collaboration Workshops\",\"Free Career Counselling for Staff Children\",\"Educator Wellness & Engagement Activities\",\"Inclusive University Culture\",\"Annual Staff Family Reconnect Meets\"]},{\"id\":\"environment-club\",\"name\":\"Environment Club\",\"desig\":\"Eco-Conscious Practices, Conservation Campaigns & Carbon Neutrality\",\"desk_label\":\"Sustainability & Planetary Stewardship\",\"desk_icon\":\"fa-leaf\",\"pill_text\":\"Mission 1,101 Trees (World Env Day – 15 Aug 2026)\",\"pill_icon\":\"fa-star\",\"visual_bg\":\"linear-gradient(145deg, #14532D 0%, #15803D 60%, #16A34A 100%)\",\"visual_icon\":\"fa-tree\",\"visual_cat\":\"Green Campus Mission\",\"visual_name\":\"Environment Club\",\"visual_tag\":\"1,101 Trees Target\",\"quote\":\"At Bhabha University, sustainability is a way of life — nurturing environmentally responsible citizens for a greener tomorrow.\",\"body_p1\":\"At Bhabha University, sustainability is a way of life. Through awareness campaigns, conservation initiatives and eco-conscious practices, the <strong>Environment Club</strong> nurtures environmentally responsible citizens.\",\"body_p2\":\"As a major Green Initiative & Commitment, the University has undertaken a mission to plant <strong>1,101 trees between 5th June (World Environment Day) and 15th August 2026</strong>, further enriching our already lush green 32-acre campus and reinforcing our vision for a greener and more sustainable future.\",\"chips\":[\"Mission 1,101 Trees Plantation Drive\",\"5th June to 15th August 2026 Commitment\",\"Eco-Conscious Campus Lifestyle\",\"Water Conservation & Solar Audits\",\"Zero-Plastic Awareness Drives\"]},{\"id\":\"legal-aid\",\"name\":\"Legal Aid Clinic\",\"desig\":\"Free Legal Consultation, Legal Awareness & Community Social Justice\",\"desk_label\":\"Access to Justice & Constitutional Literacy\",\"desk_icon\":\"fa-balance-scale\",\"pill_text\":\"Hundreds of Free Consultations & Support\",\"pill_icon\":\"fa-star\",\"visual_bg\":\"linear-gradient(145deg, #451A03 0%, #78350F 60%, #92400E 100%)\",\"visual_icon\":\"fa-gavel\",\"visual_cat\":\"Social Justice\",\"visual_name\":\"Legal Aid Clinic\",\"visual_tag\":\"18+ Years Service\",\"quote\":\"Committed to the ideals of justice and social responsibility — empowering individuals through knowledge and free access to justice.\",\"body_p1\":\"Committed to the ideals of justice and social responsibility, the <strong>Legal Aid Clinic</strong> provides free legal consultation, legal awareness and community support, empowering individuals through knowledge and access to justice.\",\"body_p2\":\"Over the last <strong>18 years</strong>, the clinic has facilitated hundreds of free legal consultations and guidance sessions, reflecting Bhabha University\'s enduring commitment towards Social Justice and Community Service. Law students gain invaluable pro-bono clinical apprenticeship under the guidance of seasoned advocates and legal scholars.\",\"chips\":[\"18+ Years of Enduring Pro-Bono Service\",\"Hundreds of Free Legal Consultations\",\"Community Legal Literacy Camps\",\"Rights Awareness for Underprivileged\",\"Clinical Student Advocate Training\"]},{\"id\":\"khelo-bhabha\",\"name\":\"Khelo Bhabha — Sports Club\",\"desig\":\"Fitness, Discipline, Teamwork, Inter-University Championships & Sportsmanship\",\"desk_label\":\"Athletic Excellence & Physical Fitness\",\"desk_icon\":\"fa-soccer-ball-o\",\"pill_text\":\"Fitness, Teamwork & Sportsmanship\",\"pill_icon\":\"fa-star\",\"visual_bg\":\"linear-gradient(145deg, #7C2D12 0%, #C2410C 60%, #EA580C 100%)\",\"visual_icon\":\"fa-trophy\",\"visual_cat\":\"Sports & Athletics\",\"visual_name\":\"Khelo Bhabha\",\"visual_tag\":\"Fit Campus Initiative\",\"quote\":\"Celebrating the spirit of fitness, discipline, teamwork and sportsmanship — pursuing athletic excellence both on and off the field.\",\"body_p1\":\"<strong>Khelo Bhabha</strong> celebrates the spirit of fitness, discipline, teamwork and sportsmanship, encouraging students to pursue excellence both on and off the field.\",\"body_p2\":\"Equipped with extensive outdoor sports grounds and indoor sports complexes, the club organizes annual university leagues, inter-departmental tournaments in cricket, football, basketball, and volleyball, while nurturing top athletic talent for state and national collegiate championships.\",\"chips\":[\"Annual Inter-Departmental Sports Meet\",\"Cricket, Football & Volleyball Leagues\",\"State & National Championship Representation\",\"Indoor Gymnasium & Badminton Courts\",\"Mindful Fitness & Yoga Camps\"]},{\"id\":\"nav-grah-vatika\",\"name\":\"Nav Grah Vatika\",\"desig\":\"Nakshatra Shastra, Sacred Celestial Flora, Indigenous Species & Cosmic Ecology\",\"desk_label\":\"Ancient Wisdom & Botanical Biodiversity\",\"desk_icon\":\"fa-sun-o\",\"pill_text\":\"Nakshatra Shastra & Ecological Heritage\",\"pill_icon\":\"fa-star\",\"visual_bg\":\"linear-gradient(145deg, #1E3A8A 0%, #1E40AF 60%, #0369A1 100%)\",\"visual_icon\":\"fa-globe\",\"visual_cat\":\"Ecological Heritage\",\"visual_name\":\"Nav Grah Vatika\",\"visual_tag\":\"9 Sacred Celestial Trees\",\"quote\":\"Harmonizing India\'s ancient ecological wisdom and Nakshatra Shastra with indigenous biodiversity conservation and cosmic consciousness.\",\"body_p1\":\"Inspired by India\'s ancient wisdom and the science of <strong>Nakshatra Shastra</strong>, <strong>Nav Grah Vatika</strong> is a unique initiative of Bhabha University, Bhopal.\",\"body_p2\":\"Designed around the traditional association of sacred trees with the nine celestial bodies, it stands as a tribute to our ecological heritage, promoting the restoration of indigenous tree species, biodiversity conservation and harmony between nature, culture and cosmic consciousness.\",\"chips\":[\"9 Celestial Sacred Trees Garden\",\"Nakshatra Shastra Botanical Association\",\"Indigenous Tree Species Restoration\",\"Herbal & Medicinal Plant Conservation\",\"Mindful Nature Harmony & Research\"]},{\"id\":\"edc-cell\",\"name\":\"Entrepreneurship Development Cell (EDC)\",\"desig\":\"Startup Mentorship, Cottage Industries Incubation, Product Development & Enterprise\",\"desk_label\":\"Innovation, Incubation & Self-Reliance\",\"desk_icon\":\"fa-rocket\",\"pill_text\":\"Mentored Thousands in Practical Industry Skills\",\"pill_icon\":\"fa-star\",\"visual_bg\":\"linear-gradient(145deg, #701A75 0%, #86198F 60%, #A21CAF 100%)\",\"visual_icon\":\"fa-lightbulb-o\",\"visual_cat\":\"Startup & Enterprise\",\"visual_name\":\"EDC Cell\",\"visual_tag\":\"Cottage Industry MSME\",\"quote\":\"Cultivating innovation, leadership and enterprise by encouraging students to transform ideas into viable ventures.\",\"body_p1\":\"The <strong>Entrepreneurship Development Cell</strong> cultivates innovation, leadership and enterprise by encouraging students to transform ideas into impactful ventures through mentorship, industry interaction and entrepreneurial exposure.\",\"body_p2\":\"Over the years, the Cell has mentored <strong>thousands of aspiring entrepreneurs</strong> in developing practical skills for establishing cottage industries, including the production of <strong>soaps, detergents, skin creams, nail paint removers, phenyl and other sustainable livelihood products</strong>, fostering self-reliance and entrepreneurial thinking.\",\"chips\":[\"Cottage Industry Practical Skill Incubation\",\"Production of Soaps, Detergents & Creams\",\"Mentored Thousands of Young Entrepreneurs\",\"Sustainable Livelihood MSME Training\",\"Angel Investor & Industry Exposure\"]},{\"id\":\"ad-mad\",\"name\":\"AD-MAD Club\",\"desig\":\"Creative Communications, Commercial Jingles, Campaign Pitching & Brand Strategy\",\"desk_label\":\"Branding, Advertising & Strategic Marketing\",\"desk_icon\":\"fa-video-camera\",\"pill_text\":\"Persuasion, Branding & Media Strategy\",\"pill_icon\":\"fa-star\",\"visual_bg\":\"linear-gradient(145deg, #0F172A 0%, #1E293B 60%, #334155 100%)\",\"visual_icon\":\"fa-bullhorn\",\"visual_cat\":\"Branding & Media\",\"visual_name\":\"AD-MAD Club\",\"visual_tag\":\"Strategic Persuasion\",\"quote\":\"A creative hub for aspiring communicators and marketers, nurturing the art of persuasion, branding, advertising and strategic media.\",\"body_p1\":\"The <strong>AD-MAD Club</strong> is a creative hub for aspiring communicators and marketers, nurturing the art of persuasion, branding, advertising and strategic marketing, preparing students for the ever-evolving world of business and media.\",\"body_p2\":\"Through high-energy ad-making hackathons, jingle composition competitions, viral marketing case studies, and corporate pitch simulations, members learn how to craft compelling messages that captivate global audiences.\",\"chips\":[\"Live Ad-Film & Jingle Competitions\",\"Brand Strategy & Positioning Labs\",\"Corporate Pitch Simulation & Storytelling\",\"Digital Marketing & Viral Campaigns\",\"Radio & Broadcast Media Collaborations\"]}],\"cta\":{\"heading\":\"Join a University Club & Lead with Purpose!\",\"desc\":\"Discover your passion, collaborate with passionate peers, organize flagship events, and build lifelong leadership skills. Open to all registered undergraduate, postgraduate, and diploma students.\",\"btn1_text\":\"Join a Club Today\",\"btn1_url\":\"enquiry.php\",\"btn2_text\":\"Contact Club Coordinators\",\"btn2_url\":\"contact.php\"}}', '1', '2026-09-29 12:31:00', '2026-10-05 11:15:44'),
