('36', 'campus_life', 'campus-life', 'Campus Life - Student Events, Sports & World-Class Infrastructure | Bhabha University Bhopal', 'Vibrant Campus Life', 'Vibrant <em>Campus Life</em>', 'Experience 32 acres of academic innovation, active student clubs, grand cultural fests, sports excellence, and world-class living facilities.', '{\"meta_description\":\"Experience life at Bhabha University Bhopal — vibrant cultural fests, sports championships, student clubs, 32-acre green campus, modern hostels, and state-of-the-art infrastructure.\",\"meta_keywords\":\"Bhabha University campus life, student life Bhopal, cultural fest Tarang, sports meet, university hostels, campus infrastructure, university clubs, student events\",\"page_icon\":\"fa-compass\",\"stats\":[{\"icon\":\"fa-tree\",\"class\":\"is-green\",\"number\":\"32\",\"symbol\":\"+\",\"label\":\"Lush Green Acres\"},{\"icon\":\"fa-calendar-check-o\",\"class\":\"is-amber\",\"number\":\"50\",\"symbol\":\"+\",\"label\":\"Annual Events & Fests\"},{\"icon\":\"fa-users\",\"class\":\"is-blue\",\"number\":\"8\",\"symbol\":\"+\",\"label\":\"Student Clubs & Cells\"},{\"icon\":\"fa-flask\",\"class\":\"is-indigo\",\"number\":\"120\",\"symbol\":\"+\",\"label\":\"Hi-Tech Labs & Studios\"},{\"icon\":\"fa-sun-o\",\"class\":\"is-gold\",\"number\":\"100\",\"symbol\":\"%\",\"label\":\"Solar-Powered Campus\"}],\"events_sec\":{\"badge\":\"Student Celebrations\",\"badge_icon\":\"fa-calendar-o\",\"title\":\"Events, Fests & <em>Youth Energy</em>\",\"desc\":\"At Bhabha University, learning extends far beyond lecture halls. From grand stage performances and tech hackathons to culinary carnivals and social service camps, campus life is alive with creativity, friendship, and leadership.\",\"items\":[{\"title\":\"Annual Youth Cultural Fest — \\\"Tarang\\\"\",\"image\":\"upload/gallery/large/f81d40b399d52222915976848a04afa8.jpg\",\"pill_icon\":\"fa-music\",\"pill_text\":\"Cultural Fest\",\"text\":\"A multi-day extravaganza where students across all institutes unite to celebrate music, drama, fashion shows, and performing arts on grand auditorium and open-air stages.\",\"tags\":[\"Music & Dance\",\"Theater\",\"Celebrity Evenings\"],\"modal_title\":\"Annual Cultural Fest — Tarang\",\"modal_desc\":\"Vibrant stage performances, classical and contemporary dance competitions, rock band shows, and theatrical showcases on our open-air university stage.\"},{\"title\":\"Freshers\' Welcome Carnival & Talent Hunt\",\"image\":\"upload/gallery/large/3f8bfe94415a00337c91ccefe3f6ae22.jpg\",\"pill_icon\":\"fa-handshake-o\",\"pill_text\":\"Induction\",\"text\":\"Every new academic journey begins with warmth, mentorship, and celebration. Incoming students showcase their unique talents, build lasting friendships, and integrate smoothly into university life.\",\"tags\":[\"Talent Rounds\",\"Peer Bonding\",\"Mentorship\"],\"modal_title\":\"Welcome Freshers Carnival\",\"modal_desc\":\"Welcoming incoming batches with talent rounds, creative games, peer mentorship, and dynamic student connections.\"},{\"title\":\"Orientation Program & Leadership Conclaves\",\"image\":\"upload/gallery/large/9107c678caa82c85e369f38c8c6cbe16.jpg\",\"pill_icon\":\"fa-graduation-cap\",\"pill_text\":\"Academic Induction\",\"text\":\"Held inside the air-conditioned Central Auditorium, orientation sessions bridge the gap between school and professional university studies, featuring industry leaders and distinguished alumni.\",\"tags\":[\"Academic Vision\",\"Career Guidance\",\"Industry Talks\"],\"modal_title\":\"University Orientation & Convocation Assembly\",\"modal_desc\":\"Academic induction, leadership keynote addresses, and inspiring career orientations inside the Central Auditorium.\"},{\"title\":\"Annual Hospitality & Culinary Carnival\",\"image\":\"upload/gallery/large/c3a81fc4f56922a13272a69d03f0081b.jpg\",\"pill_icon\":\"fa-cutlery\",\"pill_text\":\"Culinary Arts\",\"text\":\"Organized by our School of Hotel Management & Catering Technology, students conceptualize themed pop-up cafes, live pastry kitchens, and food tasting counters across open lawns.\",\"tags\":[\"Hotel Mgmt\",\"Live Kitchens\",\"Student Enterprise\"],\"modal_title\":\"Annual Hospitality Food Festival\",\"modal_desc\":\"Live culinary stalls, multi-cuisine cooking demonstrations, and student entrepreneurship food counters organized by Hotel Management students.\"},{\"title\":\"Engineer\'s Day & National Science Fair\",\"image\":\"upload/gallery/large/00ddc9caf03d120b67ca736c80de9658.jpg\",\"pill_icon\":\"fa-cogs\",\"pill_text\":\"Tech Innovation\",\"text\":\"An intellectual showcase of robotics, automated hardware models, renewable energy devices, and medical software applications built independently by student engineering squads.\",\"tags\":[\"Robotics\",\"AI & IoT\",\"Model Demonstrations\"],\"modal_title\":\"Engineer\'s Day Tech Expo\",\"modal_desc\":\"Students presenting working robotics, IoT smart farming prototypes, renewable solar models, and software creations.\"},{\"title\":\"Formula Student & Automotive Vehicle Project\",\"image\":\"upload/gallery/large/5b8e9565e03c670d630c62ada74bfa25.jpg\",\"pill_icon\":\"fa-car\",\"pill_text\":\"Automotive Lab\",\"text\":\"Mechanical and electrical engineering students design and build competitive race karts, exploring electric powertrain integration, suspension ergonomics, and on-track endurance trials.\",\"tags\":[\"Motorsport\",\"Hands-on R&D\",\"Chassis Fabrication\"],\"modal_title\":\"Formula Student & Go-Kart Racing Project\",\"modal_desc\":\"Complete fabrication, chassis welding, engine tuning and track testing of electric and combustion race vehicles by student engineers.\"},{\"title\":\"NCC Cadets & Youth Leadership Training\",\"image\":\"upload/gallery/large/efce40fadd861f6910b310d1e1a81826.jpg\",\"pill_icon\":\"fa-shield\",\"pill_text\":\"NCC Wing\",\"text\":\"Building patriotism, discipline, and physical fitness, our active NCC wing participates in Republic Day parades, adventure camps, firing ranges, and national integration expeditions.\",\"tags\":[\"Army Wing\",\"Discipline\",\"Parade Training\"],\"modal_title\":\"NCC Unit Drill & National Youth Leadership\",\"modal_desc\":\"Disciplined parade training, obstacle courses, national camps, and character building under the University NCC Army Wing.\"},{\"title\":\"Blood Donation & Community Outreach Camps\",\"image\":\"upload/gallery/large/0f625636125ac766ccba02c59bc086f5.jpg\",\"pill_icon\":\"fa-heartbeat\",\"pill_text\":\"Social Service\",\"text\":\"Instilling social consciousness, student volunteers regularly organize voluntary blood donation camps, free dental checkups, rural literacy campaigns, and eco-plantation drives across Bhopal.\",\"tags\":[\"Community Aid\",\"Red Cross\",\"NSS Volunteers\"],\"modal_title\":\"NSS Mega Blood Donation & Healthcare Camp\",\"modal_desc\":\"Over 300+ units of blood collected in university campus camps in collaboration with Red Cross and government civil hospitals.\"},{\"title\":\"Corporate Industrial & Field Study Tours\",\"image\":\"upload/gallery/large/7784e47dc525c0cfb55a3854d0ab3010.jpg\",\"pill_icon\":\"fa-industry\",\"pill_text\":\"Industry Connect\",\"text\":\"Real-world corporate exposure through regular industrial tours to BHEL, pharmaceutical manufacturing plants, IT software hubs, and civil engineering infrastructure projects.\",\"tags\":[\"Plant Tours\",\"Corporate Interaction\",\"Experiential Learning\"],\"modal_title\":\"Industrial Field Exposure Visits\",\"modal_desc\":\"Student cohorts touring major pharmaceutical manufacturing plants, automated factories, and technical production facilities.\"}]},\"sports_sec\":{\"badge\":\"Athletics & Wellness\",\"badge_icon\":\"fa-trophy\",\"title\":\"Sports Grounds, Tournaments & <em>Fitness Suite</em>\",\"desc\":\"Physical well-being and competitive spirit are vital pillars at Bhabha University. With tournament-standard cricket grounds, volleyball arenas, gymnasium suites, and indoor recreation, sports enthusiasts flourish every single day.\",\"items\":[{\"title\":\"Cricket Stadium & Annual Premier League\",\"image\":\"upload/gallery/large/cd3e8ce169d796421247b396bb3bfecb.jpg\",\"pill_icon\":\"fa-trophy\",\"pill_text\":\"Cricket Ground\",\"text\":\"Our expansive cricket ground features turf pitches, boundary fencing, and spectator pavilions. The annual Bhabha Champions Trophy brings thrilling matches, live commentary, and student team spirit.\",\"tags\":[\"Inter-College League\",\"Turf Wickets\",\"Day Tournaments\"],\"modal_title\":\"Cricket Championship & Tournament Matches\",\"modal_desc\":\"Full-sized lush green cricket stadium hosting inter-departmental championships and university state-level leagues.\"},{\"title\":\"Fully Equipped Gymnasium & Strength Suite\",\"image\":\"upload/infrastructure/08ba91f6cd604afe6629e3c47afc8dfa.jpg\",\"pill_icon\":\"fa-heartbeat\",\"pill_text\":\"Gymnasium\",\"text\":\"Designed to keep our campus community fit and active, the air-conditioned gymnasium offers cardio machines, multi-station weight rigs, dumbbells, and guidance from qualified physical education mentors.\",\"tags\":[\"Strength Training\",\"Cardio Suite\",\"Personal Trainers\"],\"modal_title\":\"Modern Campus Gymnasium Suite\",\"modal_desc\":\"Professional fitness equipment, strength training stations, treadmills, free weights, and fitness trainers for students and staff.\"},{\"title\":\"Sports Honors, Medals & Annual Awards\",\"image\":\"upload/gallery/large/94b8b12372e5b74acca5e7ff2d2412c3.jpg\",\"pill_icon\":\"fa-star\",\"pill_text\":\"Athlete Honors\",\"text\":\"Every athletic achievement is celebrated. State, national, and university-level tournament winners receive trophies, medals, sports scholarships, and university certificates of excellence.\",\"tags\":[\"Medal Winners\",\"Sports Quota\",\"University Colors\"],\"modal_title\":\"Sports Honors & Student Award Felicitations\",\"modal_desc\":\"Recognizing university athletes, inter-varsity medalists, and champions during annual award galas.\"}]},\"clubs_sec\":{\"title\":\"Student Clubs & Creative Societies\",\"desc\":\"Clubs at Bhabha University empower students to lead initiatives, explore diverse hobbies, nurture mental wellness, and create social impact alongside their degree.\"},\"infra_sec\":{\"badge\":\"32-Acre Campus\",\"badge_icon\":\"fa-building-o\",\"title\":\"World-Class <em>Campus Infrastructure</em>\",\"desc\":\"Every corner of Bhabha University is built with purpose. Explore our air-conditioned convention auditoriums, high-tech simulation laboratories, lush eco-gardens, on-campus hostels, and community radio broadcasting studios.\",\"items\":[{\"anchor_id\":\"\",\"title\":\"Central Auditorium & Convention Hall\",\"image\":\"upload/infrastructure/2aa0d1727f2df6a9ddfa7bb009eb7873.jpg\",\"pill_icon\":\"fa-microphone\",\"pill_text\":\"Auditorium\",\"text\":\"Equipped with 600+ plush seats, advanced digital surround sound, theatrical stage spotlights, and HD presentation systems for university convocations, national symposia, and cultural galas.\",\"tags\":[\"600+ Seats\",\"Acoustic Audio\",\"Central A/C\"],\"modal_title\":\"Central Auditorium & Conference Facility\",\"modal_desc\":\"Air-conditioned 600+ capacity auditorium with high-definition projection, acoustic sound engineering, and stage lighting for convocations, summits and national conferences.\"},{\"anchor_id\":\"\",\"title\":\"Interactive Smart Digital Lecture Theaters\",\"image\":\"upload/infrastructure/83e285d874ee031ad471ea4df94a1945.jpg\",\"pill_icon\":\"fa-desktop\",\"pill_text\":\"Smart Class\",\"text\":\"Step-tiered lecture theaters equipped with multimedia ceiling projectors, interactive whiteboards, high-fidelity microphones, and comfortable seating to facilitate active pedagogical discussions.\",\"tags\":[\"Digital Projectors\",\"Tiered Theaters\",\"Wi-Fi Enabled\"],\"modal_title\":\"Smart Digital Classrooms\",\"modal_desc\":\"Digital smart boards, lecture recording systems, audio-visual enhancements and ergonomic seating across every academic department.\"},{\"anchor_id\":\"\",\"title\":\"Central Library & E-Resource Center\",\"image\":\"upload/infrastructure/acacb02dda9b764fac164d4397a2accd.jpg\",\"pill_icon\":\"fa-book\",\"pill_text\":\"Central Library\",\"text\":\"Spanning multiple wings, our automated library provides thousands of academic volumes, reference encyclopedias, national journals, research databases (IEEE, DELNET, Springer), and quiet research cabins.\",\"tags\":[\"75,000+ Books\",\"Digital Journals\",\"Reading Halls\"],\"modal_title\":\"Central Library & Knowledge Hub\",\"modal_desc\":\"Over 75,000+ text volumes, international research journals, DELNET e-resources, and silent study chambers.\"},{\"anchor_id\":\"\",\"title\":\"Central Computer Center & AI Cloud Lab\",\"image\":\"upload/infrastructure/b6123df20111594aa04d8b15dd6ce2af.jpg\",\"pill_icon\":\"fa-laptop\",\"pill_text\":\"IT Infrastructure\",\"text\":\"Equipped with hundreds of latest-generation computer nodes, gigabit internet, CAD/CAM design tools, programming compilers, and AI machine-learning development suites for student coders.\",\"tags\":[\"Gigabit LAN\",\"Python & Java Labs\",\"Cloud Software\"],\"modal_title\":\"Central Computer Center & AI Labs\",\"modal_desc\":\"Networked high-performance workstations, licensed simulation software, high-speed optical fiber connectivity, and dedicated coding terminals.\"},{\"anchor_id\":\"hostels\",\"title\":\"Boys & Girls Hostels — Home Away from Home\",\"image\":\"upload/infrastructure/f26b29937f258d4966b0be4de6bea02d.jpg\",\"pill_icon\":\"fa-home\",\"pill_text\":\"Student Hostels\",\"text\":\"Safe and comfortable on-campus living with furnished rooms, round-the-clock security, continuous power backup, resident faculty wardens, common rooms with televisions, and laundry facilities.\",\"tags\":[\"Separate Hostels\",\"24/7 Gated Security\",\"RO Water\"],\"modal_title\":\"On-Campus Student Hostels\",\"modal_desc\":\"Separate residential halls for boys and girls with 24x7 security guards, CCTV surveillance, Wi-Fi connectivity, RO drinking water, and indoor recreational rooms.\"},{\"anchor_id\":\"\",\"title\":\"Hygienic Multi-Cuisine Food Court & Canteen\",\"image\":\"upload/infrastructure/3864d09b8c0761c29ab3d67b49585238.jpg\",\"pill_icon\":\"fa-coffee\",\"pill_text\":\"Cafeteria\",\"text\":\"The lively social hub of the campus where students unwind between lectures. Serving vegetarian, nutritious home-style meals, breakfast, fresh juices, and evening refreshments under strict quality standards.\",\"tags\":[\"Hygienic Kitchen\",\"Budget-Friendly\",\"Social Hub\"],\"modal_title\":\"Multi-Cuisine Campus Cafeteria\",\"modal_desc\":\"Spacious and hygienic food court serving hot nutritious meals, snacks, coffee, and beverages throughout the day.\"},{\"anchor_id\":\"\",\"title\":\"Popcorn 90.8 FM — Campus Community Radio\",\"image\":\"upload/infrastructure/9d2419cc88e43953ae02ef09e8d0bd2c.jpg\",\"pill_icon\":\"fa-bullhorn\",\"pill_text\":\"Radio Popcorn 90.8\",\"text\":\"The university houses an authorized community FM radio channel. Students gain practical broadcast experience as Radio Jockeys, sound engineers, voice-over artists, and news correspondents.\",\"tags\":[\"Live FM Station\",\"RJ Opportunities\",\"Audio Studio\"],\"modal_title\":\"Radio Popcorn 90.8 FM Community Station\",\"modal_desc\":\"Madhya Pradesh\'s premier university community radio station where journalism and mass media students script, voice, and broadcast shows daily.\"},{\"anchor_id\":\"\",\"title\":\"Clean Solar Power Plant & Green Campus\",\"image\":\"upload/infrastructure/ed3185628b9828212309305234c8a863.jpg\",\"pill_icon\":\"fa-sun-o\",\"pill_text\":\"Green Energy\",\"text\":\"Pioneering sustainable education in Central India, our on-campus solar infrastructure generates hundreds of kilowatts of clean green power, reducing carbon footprint while acting as a live research site.\",\"tags\":[\"100% Sustainable\",\"Clean Energy\",\"Live Solar R&D\"],\"modal_title\":\"University Solar Power Plant\",\"modal_desc\":\"Extensive rooftop and ground solar arrays generating clean renewable electricity, making Bhabha University a green eco-campus.\"},{\"anchor_id\":\"\",\"title\":\"Dedicated City-Wide Transport Bus Network\",\"image\":\"upload/infrastructure/1861bfeabedd25b52f2192d45a03c7f7.jpg\",\"pill_icon\":\"fa-bus\",\"pill_text\":\"Transport\",\"text\":\"Ensuring reliable and secure commutes for day scholars, a dedicated fleet of university buses operates along dozens of scheduled routes spanning Bhopal city, Bairagarh, Kolar, MP Nagar, and suburbs.\",\"tags\":[\"City-Wide Routes\",\"Safe Commute\",\"GPS Fleet\"],\"modal_title\":\"University Transport Fleet\",\"modal_desc\":\"Dedicated fleet of modern university buses traversing safe routes across all corners of Bhopal, Mandideep, and nearby regions.\"}]},\"cta\":{\"heading\":\"Ready to Experience Bhabha Campus Life?\",\"desc\":\"Step inside our 32-acre thriving campus. Connect with counselors, take a guided tour of our laboratories and hostels, or begin your admission process today.\",\"btn1_text\":\"Apply For Admission 2026-27\",\"btn1_url\":\"enquiry.php\",\"btn2_text\":\"Virtual Campus Tour\",\"btn2_url\":\"virtual.php\"}}', '1', '2026-10-05 11:15:44', '2026-10-05 11:15:44'),
('37', 'home', 'home_result_popup', '', NULL, NULL, NULL, '{\n    \"enabled\": 1,\n    \"header_title\": \"Important Notices & Results\",\n    \"header_subtitle\": \"Official circulars & declared semester examination marks\",\n    \"header_icon\": \"fa fa-bell\",\n    \"result_btn_text\": \"View Result ↗\",\n    \"result_btn_link\": \"https://bhabha.accsofterp.com/Accsoft/StudentLogin.aspx\",\n    \"close_btn_text\": \"Got it, Close\",\n    \"show_dont_show_today\": 1,\n    \"left_achiever_enabled\": 1,\n    \"achiever_pill\": \"STAR MILESTONE • ISRO\",\n    \"achiever_image\": \"govind-singh-isro.jpg\",\n    \"achiever_caption\": \"Govind Singh (M.Tech) selected as Scientist/Engineer \'SC\' at URSC, ISRO Bengaluru.\",\n    \"achiever_cta_text\": \"Read Press Coverage\",\n    \"achiever_cta_link\": \"news.php?id=203\"\n}', '1', '2026-10-05 11:29:04', '2026-10-05 11:29:04'),
('38', 'campus_life', 'hostel', 'Hostel & Residential Life', 'A Home Away From Home', 'On-Campus Student Residences', 'Comfortable, secure, and modern on-campus living facilities for boys and girls with 24x7 power backup, high-speed Wi-Fi, hygienic dining, and dedicated wardens.', '{\"page_icon\":\"fa-home\",\"featured_image\":\"upload/infrastructure/f26b29937f258d4966b0be4de6bea02d.jpg\",\"image_caption\":\"Bhabha University On-Campus Residential Hostel Blocks & Living Quarters\",\"overview_lead\":\"Bhabha University provides comprehensive residential accommodations that foster holistic academic progress, personal camaraderie, and peace of mind. Nestled within our lush 32-acre secured campus in Bhopal, the university offers separate, spacious hostels for male and female scholars with full residential oversight.\",\"overview_p2\":\"The hostel community brings together students from diverse states and cultural backgrounds across India and international regions, creating a truly inclusive, cosmopolitan fraternity. Every resident enjoys an environment engineered for focused study, sound rest, and vibrant peer collaboration.\",\"features\":[{\"icon\":\"fa-bed\",\"title\":\"Furnished Rooms\",\"desc\":\"Single, double, and triple sharing rooms equipped with ergonomic study tables, cushioned chairs, wardrobes, and quality mattresses.\"},{\"icon\":\"fa-cutlery\",\"title\":\"Hygienic Dining Mess\",\"desc\":\"Modern steam-powered kitchen serving 4 nutritious, wholesome meals daily (Breakfast, Lunch, Evening Snacks & Dinner) under FSSAI supervision.\"},{\"icon\":\"fa-wifi\",\"title\":\"High-Speed Campus Wi-Fi\",\"desc\":\"Dedicated fiber-optic internet connectivity available across all hostel wings for academic research and virtual lectures.\"},{\"icon\":\"fa-shield\",\"title\":\"24x7 CCTV & Security\",\"desc\":\"Round-the-clock trained security guards, biometric turnstile entry, and 100+ high-definition surveillance cameras ensuring total safety.\"},{\"icon\":\"fa-bolt\",\"title\":\"Continuous Power & Water\",\"desc\":\"Uninterrupted electricity with silent heavy-duty generator backup and multi-stage commercial RO purified drinking water stations.\"},{\"icon\":\"fa-user-md\",\"title\":\"Medical & Emergency Care\",\"desc\":\"On-campus health clinic with resident doctors, routine wellness checkups, first-aid suites, and 24x7 ambulance service on standby.\"}],\"detail_title\":\"Room Types & Hostel Wings\",\"cta_title\":\"Need Hostel Admission Guidance?\",\"cta_desc\":\"Contact the Chief Warden Office for room availability, allotment rules, and fee details.\",\"cta_btn_text\":\"Apply for Hostel\",\"cta_btn_url\":\"enquiry.php\"}', '1', '2026-10-08 12:17:19', '2026-10-08 12:39:43'),
('39', 'campus_life', 'cafeteria', 'Cafeteria & Food Court', 'Dining & Refreshment', 'Central Cafeteria & Dining Hubs', 'Nutritious, hygienic, and multi-cuisine culinary hubs across campus — from freshly prepared North & South Indian meals to bakery snacks, juice bars, and coffee corners.', '{\"page_icon\":\"fa-cutlery\",\"featured_image\":\"upload/infrastructure/3864d09b8c0761c29ab3d67b49585238.jpg\",\"image_caption\":\"Bhabha University Campus Canteen & Multi-Cuisine Food Court\",\"overview_lead\":\"At Bhabha University, good food and good health go hand-in-hand. The Central Campus Food Court spans a vibrant, airy 500-seater dining complex designed to provide students, faculty, and visiting guests with high-quality, delicious, and balanced meals throughout the day.\",\"overview_p2\":\"Operating from 8:00 AM to 8:30 PM, the cafeteria serves as one of the most animated and sociable hubs on campus — an ideal spot for lively debates over coffee, project brainstorming sessions, or unwinding between lectures.\",\"features\":[{\"icon\":\"fa-certificate\",\"title\":\"FSSAI Certified Hygiene\",\"desc\":\"Strict food safety compliance, regular surprise health audits, and commercial stainless steel cooking equipment ensure impeccable hygiene.\"},{\"icon\":\"fa-tint\",\"title\":\"RO Purified Water\",\"desc\":\"100% of food preparation and public drinking water points utilize advanced industrial RO filtration and UV purification systems.\"},{\"icon\":\"fa-coffee\",\"title\":\"Nescafe & Tea Lounges\",\"desc\":\"Branded kiosks offering espresso coffees, iced beverages, flavored teas, and grab-and-go energy snacks across prime academic blocks.\"},{\"icon\":\"fa-money\",\"title\":\"Subsidized Student Pricing\",\"desc\":\"University-monitored price caps maintain affordable rates for wholesome daily thalis, combos, and fresh seasonal snacks.\"}],\"detail_title\":\"Diverse Culinary Options Available\",\"cta_title\":\"Canteen Committee & Feedback\",\"cta_desc\":\"A joint Canteen Advisory Committee reviews food quality, vendor compliance, price indexes, and hygiene standards.\",\"cta_btn_text\":\"Submit Feedback\",\"cta_btn_url\":\"contact.php\"}', '1', '2026-10-08 12:17:19', '2026-10-08 12:17:19'),
('40', 'campus_life', 'transportation', 'Transport & Bus Routes', 'Safe & Punctual Transit', 'Comprehensive Fleet & City-Wide Bus Routes', 'Extensive university fleet of modern GPS-enabled buses connecting all prominent residential nodes, railway stations, and bus stands of Bhopal, Mandideep, and neighboring regions.', '{\"page_icon\":\"fa-bus\",\"featured_image\":\"upload/infrastructure/1861bfeabedd25b52f2192d45a03c7f7.jpg\",\"image_caption\":\"Bhabha University Fleet of GPS-Enabled University Transit Buses\",\"overview_lead\":\"Bhabha University maintains one of Bhopal’s most extensive student and staff transport operations. A dedicated fleet of over 50+ heavy-duty passenger buses operates daily along carefully planned arterial routes across Bhopal city, Sehore, Mandideep, Raisen, and surrounding suburbs.\",\"overview_p2\":\"Designed for safe, stress-free daily commutes, every university coach is operated by certified drivers with conductor support, speed governors, first-aid kits, and real-time GPS tracking for student security.\",\"features\":[{\"icon\":\"fa-map-marker\",\"title\":\"50+ Extensive Routes\",\"desc\":\"Comprehensive route coverage touching MP Nagar, Lalghati, BHEL, Kolar Road, Ayodhya Bypass, Hoshangabad Road, and Karond.\"},{\"icon\":\"fa-clock-o\",\"title\":\"Punctual Timings\",\"desc\":\"Strictly synchronized schedules ensuring students arrive comfortably before morning lectures and depart immediately after classes.\"},{\"icon\":\"fa-shield\",\"title\":\"GPS & Safety First\",\"desc\":\"Real-time vehicle tracking, verified drivers, speed regulators, and emergency contact numbers prominently displayed.\"},{\"icon\":\"fa-id-card\",\"title\":\"Subsidized Bus Passes\",\"desc\":\"Affordable semester and annual bus pass options with transparent seat booking for all enrolled scholars and faculty.\"}],\"detail_title\":\"Major City Route Coverage\",\"cta_title\":\"Need Transport Route Details?\",\"cta_desc\":\"Contact the Transport In-charge for route maps, timing schedules, and bus pass registration.\",\"cta_btn_text\":\"Apply for Bus Pass\",\"cta_btn_url\":\"enquiry.php\"}', '1', '2026-10-08 12:17:19', '2026-10-08 13:25:35'),
('41', 'campus_life', 'library', 'Central Library & E-Resources', 'Knowledge Sanctuary', 'Central Library & Digital Knowledge Repository', 'Comprehensive academic library housing over 1,00,000+ print volumes, thousands of peer-reviewed national & international e-journals, DELNET access, and multimedia digital reading rooms.', '{\"page_icon\":\"fa-bookmark\",\"featured_image\":\"upload/infrastructure/acacb02dda9b764fac164d4397a2accd.jpg\",\"image_caption\":\"Bhabha University Central Academic Library & Digital Reading Hall\",\"overview_lead\":\"The Central Library at Bhabha University stands as the intellectual epicentre of the institution. Spanning multiple air-conditioned floors with quiet research cubicles, the library offers an unmatched collection of engineering, medical, dental, pharmacy, law, humanities, and management literature.\",\"overview_p2\":\"Equipped with automated Koha library management software, barcode circulation, and round-the-clock digital e-library portals, scholars can effortlessly browse, reserve, and reference global academic archives.\",\"features\":[{\"icon\":\"fa-book\",\"title\":\"1,00,000+ Print Books\",\"desc\":\"Extensive curriculum textbooks, reference encyclopedias, competitive exam materials, and rare academic archives.\"},{\"icon\":\"fa-laptop\",\"title\":\"Digital Library & DELNET\",\"desc\":\"High-speed computerized terminals with subscription access to IEEE, ScienceDirect, DELNET, and National Digital Library of India.\"},{\"icon\":\"fa-clock-o\",\"title\":\"Extended Reading Hours\",\"desc\":\"Open early morning to late evening with extended night operations during mid-term and semester examination periods.\"},{\"icon\":\"fa-file-text-o\",\"title\":\"Reprographic & Printing\",\"desc\":\"On-site photocopy, document scanning, binding, and research paper printing facilities for students and faculty.\"}],\"detail_title\":\"Library Sections & Specialized Wings\",\"cta_title\":\"Digital E-Library Access\",\"cta_desc\":\"Students and faculty can access online research journals, thesis repositories, and DELNET portals using institutional ERP credentials.\",\"cta_btn_text\":\"Access E-Library\",\"cta_btn_url\":\"enquiry.php\"}', '1', '2026-10-08 12:17:19', '2026-10-08 13:25:35'),
('42', 'campus_life', 'it-labs', 'IT & Computer Labs', 'High-Tech Infrastructure', 'Advanced Computing Infrastructure & High-Speed Labs', 'Cutting-edge computing laboratories powered by enterprise workstations, gigabit fiber-optic backbone, AI/ML software suites, cloud sandboxes, and dedicated server arrays.', '{\"page_icon\":\"fa-laptop\",\"featured_image\":\"upload/infrastructure/b6123df20111594aa04d8b15dd6ce2af.jpg\",\"image_caption\":\"Bhabha University Advanced Computing & AI Lab Facility\",\"overview_lead\":\"In today’s digitized world, technical prowess begins in the lab. Bhabha University features over 15+ specialized computer laboratories equipped with more than 1,200 modern high-speed desktop terminals, high-end Intel/AMD workstations, and dedicated GPU computing servers.\",\"overview_p2\":\"All computer laboratories are interlinked via a redundant 1 Gbps leased line fiber network with enterprise hardware firewalls, uninterruptible power units, and centralized software licensing.\",\"features\":[{\"icon\":\"fa-desktop\",\"title\":\"1,200+ High-End PCs\",\"desc\":\"Intel Core i5/i7 workstations with SSD storage, high-resolution displays, and dual-boot OS environments (Linux & Windows).\"},{\"icon\":\"fa-code\",\"title\":\"Modern Software Stacks\",\"desc\":\"Industry-standard development IDEs, MATLAB, Python, Android Studio, Oracle DB, CAD/CAM tools, and cloud SDKs.\"},{\"icon\":\"fa-wifi\",\"title\":\"Gigabit Fiber Backbone\",\"desc\":\"1 Gbps dedicated internet bandwidth ensuring lag-free coding, online hackathons, and seamless research simulation.\"},{\"icon\":\"fa-cogs\",\"title\":\"AI, ML & IoT Sandboxes\",\"desc\":\"Specialized labs equipped with NVIDIA GPU hardware, Arduino, Raspberry Pi kits, and sensor arrays for prototype innovation.\"}],\"detail_title\":\"Specialized Laboratories Directory\",\"cta_title\":\"IT Helpdesk & Lab Assistance\",\"cta_desc\":\"The IT Cell provides continuous hardware maintenance, ERP support, and lab scheduling for student project teams.\",\"cta_btn_text\":\"Contact IT Cell\",\"cta_btn_url\":\"bhabhaitcell.php\"}', '1', '2026-10-08 12:17:19', '2026-10-08 13:25:35'),
('43', 'campus_life', 'health-wellness', 'Health & Wellness', 'Care & Healing', 'Comprehensive Health Services & Wellness Care', 'On-campus 100-bed hospital facility, 24x7 medical clinic, resident medical officers, dental dispensary, homoeopathic OPD, routine wellness screenings, and dedicated ambulance service.', '{\"page_icon\":\"fa-heartbeat\",\"featured_image\":\"upload/infrastructure/e24d4326ba8712763cc0e1484f66dc4d.jpg\",\"image_caption\":\"Bhabha University On-Campus Hospital & Health Clinic\",\"overview_lead\":\"The health, mental well-being, and physical safety of every Bhabha University scholar and employee are paramount. The campus is equipped with an affiliated full-fledged multi-specialty teaching hospital, dental hospital, homoeopathic clinic, and 24x7 emergency dispensary.\",\"overview_p2\":\"Staffed by qualified medical officers, nurses, dentists, and psychological counselors, our healthcare wing delivers free consultation, subsidized medicines, first aid, and immediate medical triage.\",\"features\":[{\"icon\":\"fa-user-md\",\"title\":\"Resident Medical Doctors\",\"desc\":\"Full-time physicians, pediatricians, dentists, and nurses available for routine OPD consultations and emergency care.\"},{\"icon\":\"fa-ambulance\",\"title\":\"24x7 Ambulance on Standby\",\"desc\":\"Fully equipped cardiac ambulance permanently stationed on campus for immediate transfer to specialty centers.\"},{\"icon\":\"fa-hospital-o\",\"title\":\"Teaching Hospital Access\",\"desc\":\"Access to Bhabha Medical and Dental teaching hospitals with pathology labs, dental chairs, and digital X-ray diagnostics.\"},{\"icon\":\"fa-heart\",\"title\":\"Counseling & Mental Health\",\"desc\":\"Confidential psychological guidance, stress management workshops, and student mentorship sessions through Unload Pittara.\"}],\"detail_title\":\"Healthcare Wings on Campus\",\"cta_title\":\"24x7 Medical Emergency Helpline\",\"cta_desc\":\"In case of any medical emergency on campus, contact the Health Center or Chief Warden Office immediately.\",\"cta_btn_text\":\"Call Emergency Helpline\",\"cta_btn_url\":\"tel:07554246498\"}', '1', '2026-10-08 12:17:19', '2026-10-08 13:25:35'),
('44', 'campus_life', 'sports', 'Sports & Fitness Complex', 'Champions in the Making', 'Sports Grounds, Tournaments & Fitness Suite', 'World-class outdoor sports grounds, synthetic cricket pitches, basketball courts, badminton arenas, and modern indoor gymnasium suites fostering physical excellence and team spirit.', '{\"page_icon\":\"fa-futbol-o\",\"featured_image\":\"upload/infrastructure/08ba91f6cd604afe6629e3c47afc8dfa.jpg\",\"image_caption\":\"Bhabha University Sports Complex, Cricket Stadium & Athletic Tracks\",\"overview_lead\":\"At Bhabha University, sports and physical fitness are integral pillars of the holistic student development ethos. Our sprawling 32-acre green campus boasts expansive athletic fields, floodlit courts, and professional training equipment.\",\"overview_p2\":\"From the high-stakes annual Khelo Bhabha Inter-Collegiate Championship to state-level tournaments and relaxed evening basketball games, students find ample avenues to nurture team leadership, agility, and sportsmanship.\",\"features\":[{\"icon\":\"fa-futbol-o\",\"title\":\"Full-Size Cricket & Football Turf\",\"desc\":\"Expansive green turf grounds with professional pitch markings, player pavilions, and spectator stands.\"},{\"icon\":\"fa-trophy\",\"title\":\"Basketball & Volleyball Courts\",\"desc\":\"Hardcourt basketball arenas and sand volleyball courts equipped with floodlights for evening training.\"},{\"icon\":\"fa-heartbeat\",\"title\":\"Modern Fitness Gymnasium\",\"desc\":\"Air-conditioned gymnasium featuring treadmills, weightlifting benches, resistance trainers, and fitness trainers.\"},{\"icon\":\"fa-gamepad\",\"title\":\"Indoor Sports Club\",\"desc\":\"Indoor sports pavilion hosting international-standard table tennis boards, chess zones, and carrom tables.\"}],\"detail_title\":\"Sports Facilities Directory\",\"cta_title\":\"Join Sports Teams & Tournaments\",\"cta_desc\":\"Interested in representing Bhabha University in university, state, or national championships? Contact the Physical Education Department.\",\"cta_btn_text\":\"Register for Sports\",\"cta_btn_url\":\"enquiry.php\"}', '1', '2026-10-08 12:17:19', '2026-10-08 13:25:35'),
('45', 'campus_life', 'community-service', 'Community Service & Environment', 'Social Responsibility', 'Social Responsibility, NSS & Environmental Initiatives', 'Active National Service Scheme (NSS) units, rural development adoption programs, blood donation camps, free dental checkups, and eco-friendly green campus conservation drives.', '{\"page_icon\":\"fa-leaf\",\"featured_image\":\"upload/infrastructure/ed3185628b9828212309305234c8a863.jpg\",\"image_caption\":\"Bhabha University Student Social Outreach & Environmental Awareness Drive\",\"overview_lead\":\"Bhabha University believes that true higher education must uplift society. Through our vibrant National Service Scheme (NSS) chapters, Red Cross youth wings, and social initiatives, students step beyond classrooms to serve underprivileged communities across Madhya Pradesh.\",\"overview_p2\":\"From organizing free health and dental screening camps in adopted rural villages to conducting literacy workshops and planting thousands of saplings, our scholars learn empathy, grassroots leadership, and civic duty.\",\"features\":[{\"icon\":\"fa-users\",\"title\":\"Active NSS Units\",\"desc\":\"Government-recognized National Service Scheme volunteer chapters conducting 7-day special rural development camps.\"},{\"icon\":\"fa-tint\",\"title\":\"Mega Blood Donation Camps\",\"desc\":\"Annual blood donation camps organized in partnership with Red Cross Society and regional blood banks collecting hundreds of units.\"},{\"icon\":\"fa-tree\",\"title\":\"Green Campus & Tree Plantation\",\"desc\":\"Extensive afforestation drives, 100 kWp solar energy harvest, rainwater harvesting systems, and plastic-free campus zones.\"},{\"icon\":\"fa-medkit\",\"title\":\"Rural Health Outreaches\",\"desc\":\"Free medical, dental, and eye checkup camps with free medicine distribution conducted by university doctors in tribal villages.\"}],\"detail_title\":\"Major Community Initiatives\",\"cta_title\":\"Become an NSS Volunteer\",\"cta_desc\":\"Join hands with fellow changemakers and earn official NSS certification recognized by the Ministry of Youth Affairs.\",\"cta_btn_text\":\"Join NSS Club\",\"cta_btn_url\":\"clubs.php\"}', '1', '2026-10-08 12:17:19', '2026-10-08 13:25:35'),
('46', 'campus_life', 'entrepreneurship', 'Entrepreneurship & Career Dev.', 'Incubating Future Leaders', 'Innovation Hub & Career Development Centre', 'Fostering innovation, technology startups, intellectual property creation, seed funding guidance, and executive career mentoring for ambitious young entrepreneurs.', '{\"page_icon\":\"fa-rocket\",\"featured_image\":\"upload/infrastructure/2aa0d1727f2df6a9ddfa7bb009eb7873.jpg\",\"image_caption\":\"Bhabha University Entrepreneurship Development & Incubation Centre\",\"overview_lead\":\"The Entrepreneurship Development Cell (EDC) and Incubation Center at Bhabha University empower students to transform creative ideas into scalable, commercial startups. We provide mentorship, co-working space, patent filing support, and investor networking.\",\"overview_p2\":\"Aligned with Startup India and national innovation frameworks, our incubation ecosystem offers seed funding guidance, business model validation, and technical prototyping support across software, robotics, healthcare, and agribusiness domains.\",\"features\":[{\"icon\":\"fa-lightbulb-o\",\"title\":\"Startup Incubation Hub\",\"desc\":\"Co-working spaces equipped with high-speed internet, conference rooms, prototyping labs, and administrative infrastructure.\"},{\"icon\":\"fa-users\",\"title\":\"Industry Mentorship\",\"desc\":\"Direct one-on-one mentorship from successful startup founders, venture capitalists, patent attorneys, and corporate executives.\"},{\"icon\":\"fa-file-text-o\",\"title\":\"Patent & IPR Cell\",\"desc\":\"Comprehensive legal and technical assistance for drafting, filing, and defending student patents, trademarks, and copyrights.\"},{\"icon\":\"fa-line-chart\",\"title\":\"Pitch Competitions & Hackathons\",\"desc\":\"Regular business plan challenges, angel investor demo days, and national-level hackathons with cash seed grants.\"}],\"detail_title\":\"Incubation Programs & Ecosystem\",\"cta_title\":\"Have a Startup Idea?\",\"cta_desc\":\"Submit your business plan or technical innovation to the Incubation Advisory Committee for evaluation and mentorship.\",\"cta_btn_text\":\"Apply for Incubation\",\"cta_btn_url\":\"enquiry.php\"}', '1', '2026-10-08 12:17:19', '2026-10-08 13:25:35'),
('47', 'campus_life', 'student-safety', 'Student Safety & Support', 'Multi-Layered Security', 'Security Systems & Support Cells', '24x7 guarded perimeter, biometric checkpoints, 200+ HD surveillance cameras, Anti-Ragging squads, Women’s Safety cell (ICC), and emergency medical response units ensuring total peace of mind.', '{\"page_icon\":\"fa-shield\",\"featured_image\":\"upload/infrastructure/a21a86aaaa2a4e2d73c247cdb15af08e.jpg\",\"image_caption\":\"Bhabha University 24x7 Campus Security & Regulated Checkpoints\",\"overview_lead\":\"Student security, well-being, and dignity are non-negotiable priorities at Bhabha University. Our multi-tiered campus safety framework ensures that all scholars, residential students, faculty, and visitors study and live in a tranquil, protected environment.\",\"overview_p2\":\"With a dedicated security force of trained guards, proactive anti-ragging flying squads, and active statutory grievance cells, we maintain an alert and responsive support ecosystem around the clock.\",\"features\":[{\"icon\":\"fa-ban\",\"title\":\"Anti-Ragging Squad\",\"desc\":\"Zero tolerance policy against ragging. Strict adherence to UGC guidelines with surprise squad patrols across hostels, canteens, and sports fields.\"},{\"icon\":\"fa-female\",\"title\":\"Women\'s Safety & ICC\",\"desc\":\"Active Internal Complaints Committee (ICC) ensuring strict gender sensitization, prevention of sexual harassment (POSH), and swift confidential hearings.\"},{\"icon\":\"fa-video-camera\",\"title\":\"24x7 HD CCTV Surveillance\",\"desc\":\"Over 200+ networked digital security cameras monitoring entry gates, academic corridors, common lounges, and hostel perimeter fences.\"},{\"icon\":\"fa-id-card\",\"title\":\"Biometric Access & Guards\",\"desc\":\"Trained security personnel stationed at all campus gates with biometric turnstiles and mandatory visitor verification logging.\"},{\"icon\":\"fa-fire-extinguisher\",\"title\":\"Fire & Disaster Safety\",\"desc\":\"Commercial fire hydrants, automated smoke alarms, dry powder extinguishers on every floor, and scheduled student evacuation drills.\"},{\"icon\":\"fa-user-secret\",\"title\":\"Confidential Grievance Portal\",\"desc\":\"Digital grievance redressal portal allowing students to submit academic or administrative concerns directly to the university ombudsman.\"}],\"detail_title\":\"Anti-Ragging Regulations & Penalties\",\"cta_title\":\"Campus Emergency Control Room\",\"cta_desc\":\"Save these 24x7 emergency contacts on your mobile phone: Security Chief (0755-4246498), Chief Warden, Medical Clinic.\",\"cta_btn_text\":\"Report Grievance\",\"cta_btn_url\":\"grievance.php\"}', '1', '2026-10-08 12:17:19', '2026-10-08 13:25:35'),
('48', 'campus_life', 'student-media', 'Student Media & Communication', 'Voices of Bhabha', 'Campus Broadcasting, Publications & Media Studio', 'Radio Popcorn 90.4 FM community radio, student news bulletins, digital podcast studios, university magazine editorial board, and multimedia production suites.', '{\"page_icon\":\"fa-bullhorn\",\"featured_image\":\"upload/infrastructure/9d2419cc88e43953ae02ef09e8d0bd2c.jpg\",\"image_caption\":\"Bhabha University Media Center, Radio Studio & Production Suite\",\"overview_lead\":\"The Department of Media & Journalism and student communication wings at Bhabha University provide an immersive hands-on broadcasting platform. Anchored by the celebrated Radio Popcorn 90.4 FM community radio station, students host daily shows, produce audio documentaries, and anchor campus talk shows.\",\"overview_p2\":\"Scholars also manage the editorial curation of the quarterly university newsletter, video podcasts, YouTube documentaries, and the annual student magazine.\",\"features\":[{\"icon\":\"fa-microphone\",\"title\":\"Radio Popcorn 90.4 FM\",\"desc\":\"Licensed community radio station broadcast across Bhopal featuring educational programs, student RJ shows, and public health bulletins.\"},{\"icon\":\"fa-video-camera\",\"title\":\"Chroma Studio & Production\",\"desc\":\"Professional multi-camera Chroma key studio with teleprompters, digital video mixers, and high-end video editing suites.\"},{\"icon\":\"fa-newspaper-o\",\"title\":\"Campus Magazine & Digest\",\"desc\":\"Editorial club producing student creative articles, poetry, campus chronicles, research spotlights, and photo-essays.\"},{\"icon\":\"fa-podcast\",\"title\":\"Digital Podcasts & Tech Talks\",\"desc\":\"Student-hosted podcast series discussing industry trends, alumni interviews, campus events, and expert guest lectures.\"}],\"detail_title\":\"Media Clubs & Broadcasting Wings\",\"cta_title\":\"Tune in to Radio Popcorn 90.4 FM\",\"cta_desc\":\"Listen to daily educational, cultural, and community broadcasts hosted live by our student radio jockeys.\",\"cta_btn_text\":\"Learn More About Radio\",\"cta_btn_url\":\"radio.php\"}', '1', '2026-10-08 12:17:19', '2026-10-08 13:25:35');
